.darma-loader-tetris-drop {
  position: relative;
  width: 40px;
  height: 48px;
  border: 2px solid #c7d2fe;
  border-radius: 3px;
  box-sizing: border-box;
  overflow: hidden;
  background-image:
    repeating-linear-gradient(90deg, transparent 0 9px, color-mix(in srgb, var(--loader-color, #6366f1) 12%, transparent) 9px 10px),
    repeating-linear-gradient(transparent 0 9px, color-mix(in srgb, var(--loader-color, #6366f1) 12%, transparent) 9px 10px);
}
.darma-loader-tetris-drop::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 10px;
  background: #4338ca;
}
.darma-loader-tetris-drop i {
  position: absolute;
  left: 9px;
  width: 20px;
  height: 10px;
  background: var(--loader-color, #6366f1);
  border-radius: 2px;
  animation: darma-loader-tetris-drop-fall 1.3s ease-in infinite;
}
.darma-loader-tetris-drop i::after {
  content: "";
  position: absolute;
  top: 10px;
  left: 5px;
  width: 10px;
  height: 10px;
  background: var(--loader-color, #6366f1);
  border-radius: 2px;
}
@keyframes darma-loader-tetris-drop-fall {
  0% { top: -4px; opacity: 0; }
  15% { opacity: 1; }
  70% { top: 24px; }
  85% { top: 24px; opacity: 1; }
  100% { top: -4px; opacity: 0; }
}

